import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
  random,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadAnton = makeLoadFont('Anton');

// Load bold, blocky font for the overlay text
const { fontFamily: antonFamily } = loadAnton();



export type PuzzleRevealProps = Record<string, any>;

// Helper to generate a single puzzle edge path segment
const createPuzzleEdge = (
  p1: { x: number; y: number },
  p2: { x: number; y: number },
  type: number, // 1 for outward tab, -1 for inward blank, 0 for flat
  tabDepth: number
) => {
  if (type === 0) return `L ${p2.x} ${p2.y}`;

  const dx = p2.x - p1.x;
  const dy = p2.y - p1.y;
  const len = Math.sqrt(dx * dx + dy * dy);
  
  // Normal vector scaled to tab depth. (dy, -dx) points "up/left" relative to draw direction.
  const nx = (dy / len) * tabDepth;
  const ny = (-dx / len) * tabDepth;

  const dir = type;

  // Key positions along the edge for the tab neck and bulb
  const pa_x = p1.x + dx * 0.38;
  const pa_y = p1.y + dy * 0.38;
  const pb_x = p1.x + dx * 0.62;
  const pb_y = p1.y + dy * 0.62;

  // Bezier control points to form the classic puzzle knob
  const c1_x = p1.x + dx * 0.38 + nx * (dir * 0.1);
  const c1_y = p1.y + dy * 0.38 + ny * (dir * 0.1);
  const c2_x = p1.x + dx * 0.25 + nx * dir;
  const c2_y = p1.y + dy * 0.25 + ny * dir;
  const mid_x = p1.x + dx * 0.50 + nx * dir;
  const mid_y = p1.y + dy * 0.50 + ny * dir;
  const c3_x = p1.x + dx * 0.75 + nx * dir;
  const c3_y = p1.y + dy * 0.75 + ny * dir;
  const c4_x = p1.x + dx * 0.62 + nx * (dir * 0.1);
  const c4_y = p1.y + dy * 0.62 + ny * (dir * 0.1);

  return `
    L ${pa_x} ${pa_y}
    C ${c1_x} ${c1_y}, ${c2_x} ${c2_y}, ${mid_x} ${mid_y}
    C ${c3_x} ${c3_y}, ${c4_x} ${c4_y}, ${pb_x} ${pb_y}
    L ${p2.x} ${p2.y}
  `;
};

const PuzzleReveal: React.FC<PuzzleRevealProps> = ({
  backgroundImage = "https://images.unsplash.com/photo-1513360371669-4adf3dd7dff8?q=80&w=1080&auto=format&fit=crop",
  topText = "TODAY",
  bottomText = "HAVE A GOOD DAY",
  rows = 3,
  cols = 1,
  staggerDuration = 0.4,
  backgroundColor = "#fdfdfd",
  transparentBackground = false,
  durationInSeconds = 5,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Define the puzzle bounding box to completely fill the canvas
  const puzzleWidth = width;
  const puzzleHeight = height;
  
  const startX = 0;
  const startY = 0;
  const pieceW = puzzleWidth / cols;
  const pieceH = puzzleHeight / rows;
  const tabDepth = Math.min(pieceW, pieceH) * 0.18;

  // Generate deterministic interlocking edges
  const pieces = useMemo(() => {
    const generatedPieces = [];

    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        // Inner edges logic: 
        // We use random seeds based on the shared boundary index to ensure pieces perfectly interlock.
        // A tab pointing "out" (1) on the bottom edge must be met by a blank (-1) on the top edge of the piece below.
        // Outer boundaries are set to 0 (flat) to sit perfectly flush with the canvas edge.
        
        const tTop = r === 0 
          ? 0 
          : -(random(`h-${r - 1}-${c}`) > 0.5 ? 1 : -1);
          
        const tRight = c === cols - 1 
          ? 0 
          : (random(`v-${r}-${c}`) > 0.5 ? 1 : -1);
          
        const tBot = r === rows - 1 
          ? 0 
          : (random(`h-${r}-${c}`) > 0.5 ? 1 : -1);
          
        const tLeft = c === 0 
          ? 0 
          : -(random(`v-${r}-${c - 1}`) > 0.5 ? 1 : -1);

        const x = startX + c * pieceW;
        const y = startY + r * pieceH;

        const pTL = { x, y };
        const pTR = { x: x + pieceW, y };
        const pBR = { x: x + pieceW, y: y + pieceH };
        const pBL = { x, y: y + pieceH };

        const path = `
          M ${pTL.x} ${pTL.y}
          ${createPuzzleEdge(pTL, pTR, tTop, tabDepth)}
          ${createPuzzleEdge(pTR, pBR, tRight, tabDepth)}
          ${createPuzzleEdge(pBR, pBL, tBot, tabDepth)}
          ${createPuzzleEdge(pBL, pTL, tLeft, tabDepth)}
          Z
        `;

        generatedPieces.push({ r, c, path, id: `piece-${r}-${c}` });
      }
    }
    return generatedPieces;
  }, [rows, cols, pieceW, pieceH, startX, startY, tabDepth]);

  const staggerFrames = staggerDuration * fps;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <svg width={width} height={height} viewBox={`0 0 ${width} ${height}`}>
        <defs>
          {/* Create a clipPath for every puzzle piece */}
          {pieces.map((p) => (
            <clipPath id={p.id} key={`clip-${p.id}`}>
              <path d={p.path} />
            </clipPath>
          ))}
          
          {/* Subtle drop shadow to give pieces physical thickness */}
          <filter id="piece-shadow" x="-20%" y="-20%" width="140%" height="140%">
            <feDropShadow dx="0" dy="15" stdDeviation="15" floodColor="#000" floodOpacity="0.3" />
          </filter>
        </defs>

        {pieces.map((p) => {
          // Calculate reveal timing (top-to-bottom sequence)
          const pieceIndex = p.r * cols + p.c;
          const delay = pieceIndex * staggerFrames;

          // Spring animation for popping in
          const rawScale = spring({
            frame: frame - delay,
            fps,
            config: { damping: 14, mass: 0.8, stiffness: 120 },
          });

          // Compress the scale range from 0.7 to 1 to maintain the spring bounce
          const scale = interpolate(rawScale, [0, 1], [0.7, 1]);
          const opacity = interpolate(rawScale, [0, 0.4], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });

          // Center of the piece for transform-origin
          const cx = startX + p.c * pieceW + pieceW / 2;
          const cy = startY + p.r * pieceH + pieceH / 2;

          return (
            <g
              key={p.id}
              style={{
                transformOrigin: `${cx}px ${cy}px`,
                transform: `scale(${scale})`,
                opacity: opacity,
                transition: "none",
              }}
              filter="url(#piece-shadow)"
            >
              {/* This group isolates the image and text, clipping them strictly to the piece shape */}
              <g clipPath={`url(#${p.id})`}>
                <image
                  href={backgroundImage}
                  width={width}
                  height={height}
                  preserveAspectRatio="xMidYMid slice"
                />
                
                {/* Overlay Text that gets seamlessly cut by the puzzle lines */}
                {topText && (
                  <text
                    x={width / 2}
                    y={height * 0.22}
                    textAnchor="middle"
                    dominantBaseline="middle"
                    fill="#FACC15"
                    style={{
                      fontFamily: antonFamily,
                      fontSize: 160,
                      letterSpacing: "4px",
                      textTransform: "uppercase",
                    }}
                  >
                    {topText}
                  </text>
                )}
                
                {bottomText && (
                  <text
                    x={width / 2}
                    y={height * 0.82}
                    textAnchor="middle"
                    dominantBaseline="middle"
                    fill="#FACC15"
                    style={{
                      fontFamily: antonFamily,
                      fontSize: 130,
                      letterSpacing: "2px",
                      textTransform: "uppercase",
                    }}
                  >
                    {bottomText}
                  </text>
                )}
              </g>

              {/* Physical edge highlight drawn ON TOP of the clipped content */}
              <path
                d={p.path}
                fill="none"
                stroke="rgba(255, 255, 255, 0.9)"
                strokeWidth={3}
                strokeLinejoin="round"
              />
            </g>
          );
        })}
      </svg>
    </AbsoluteFill>
  );
};

export default PuzzleReveal;